import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdminListProf = () => {
  const [professores, setProfessores] = useState([
    "Paulo Carvalho",
    "Helena Martins",
    "Carla Rodrigues",
    "Ana Paula",
    "Maria Ana",
    "Gustavo Lima",
  ]);

  const [novoProfessor, setNovoProfessor] = useState("");

  const adicionarProfessor = () => {
    if (novoProfessor.trim()) {
      setProfessores([...professores, novoProfessor]);
      setNovoProfessor("");
    }
  };

  const removerProfessor = (index) => {
    setProfessores(professores.filter((_, i) => i !== index));
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="mt-3">
        <h3>Professores</h3>
        <div className="d-flex mb-3">
          <input
            type="text"
            className="form-control me-2"
            placeholder="busque o professor pelo nome"
            value={novoProfessor}
            onChange={(e) => setNovoProfessor(e.target.value)}
          />
          <button className="btn btn-primary" onClick={adicionarProfessor}>
            Adicionar
          </button>
        </div>

        <ul className="list-group">
          {professores.map((professor, index) => (
            <li
              key={index}
              className="list-group-item d-flex justify-content-between align-items-center"
            >
              {professor}
              <div>
                <button className="btn btn-outline-primary btn-sm mx-2">
                  ✏️
                </button>
                <button
                  className="btn btn-outline-danger btn-sm"
                  onClick={() => removerProfessor(index)}
                >
                  🗑️
                </button>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default AdmListProf;
